def makeSlug(strTitle, maxLen=MAX_SLUG_LEN):
    """makes url friendly slug from a title"""
    if strTitle == None:
        return ''
    s = strTitle.lower().strip()
    s = re.sub('[^a-z0-9 -]', '', s)
    s = s.replace(' ', '-')
    while '--' in s:
        s = s.replace('--', '-')
    if len(s) > maxLen:
        s = s[0:maxLen]
    return s

